const body = $input.item.json.body || {};
const username = (body.username || '').trim().toLowerCase().replace(/^@/, '');
if (!username) throw new Error('Missing username');
return { json: { username } };

const bundle = $input.item.json.data || $input.item.json;
const profile = bundle.profile || {};
const posts = bundle.posts || [];
if (!profile.id) throw new Error('Profile not found');

const lean = {
  ig_handle: profile.ig_handle,
  followers_count: profile.followers_count,
  follower_tier: profile.follower_tier,
  city: profile.city || profile.inferred_city,
  niche: profile.niche || profile.inferred_niche,
  sub_niche: profile.sub_niche || profile.inferred_sub_niche,
  view_based_er: profile.view_based_er,
  follower_based_er: profile.follower_based_er,
  total_posts_90d: profile.total_posts_90d,
  total_brand_collaborations: profile.total_brand_collaborations,
  unique_brands_count: profile.unique_brands_count,
  consistency_score: profile.consistency_score,
  growth_potential_score: profile.growth_potential_score,
  activity_status: profile.activity_status,
  reachability_score: profile.reachability_score
};

const prompt = 'Score this influencer for campaign suitability.\n\nProfile: ' + JSON.stringify(lean) + '\n\nRecent post engagement: ' + JSON.stringify(posts.slice(0, 10).map(p => ({ likes: p.likes_count, comments: p.comments_count, views: p.views_count, type: p.type, sponsored: p.has_commercial_intent }))) + '\n\nScoring criteria (weighted):\n1. Engagement Quality (30%): rate vs tier benchmark. Nano >5%, Micro >3%, Mid >2%, Macro >1.5%.\n2. Content Consistency (20%): posting frequency, niche consistency.\n3. Audience Relevance (20%): city match, niche alignment.\n4. Collaboration Track Record (15%): past brand work, not over-saturated.\n5. Growth Potential (15%): follower/following ratio, trajectory.\n\nReturn ONLY valid JSON:\n{"priority_score": 0-100 number, "tier": "high|mid|low", "scores": {"engagement_quality": 0, "content_consistency": 0, "audience_relevance": 0, "collab_track_record": 0, "growth_potential": 0}, "strengths": [], "concerns": [], "summary": "one paragraph"}';

return { json: {
  ig_handle: profile.ig_handle,
  claude_body: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 2048,
    messages: [{ role: 'user', content: prompt }]
  }
} };

let data = {};
try {
  const txt = $input.item.json.content[0].text;
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) data = JSON.parse(m[0]);
} catch (e) { data = { priority_score: 0, tier: 'low', summary: 'Scoring failed' }; }
const ig_handle = $('Build Claude Prompt').item.json.ig_handle;

const priority_score = Math.max(0, Math.min(100, Number(data.priority_score) || 0));
const tier_raw = String(data.tier || '').toLowerCase();
const tier = ['high','mid','low'].includes(tier_raw) ? tier_raw : (priority_score >= 70 ? 'high' : priority_score >= 40 ? 'mid' : 'low');

return { json: {
  ig_handle,
  priority_score,
  tier,
  scoring_summary: String(data.summary || '').slice(0, 2000),
  scoring_strengths: Array.isArray(data.strengths) ? data.strengths : [],
  scoring_concerns: Array.isArray(data.concerns) ? data.concerns : [],
  insight_body: {
    insight_type: 'profile_summary',
    ig_handle,
    title: 'Influencer Score: ' + priority_score + '/100',
    body: String(data.summary || ''),
    score: priority_score,
    model_used: 'claude-sonnet-4',
    metadata: { tier, scores: data.scores || {}, strengths: data.strengths || [], concerns: data.concerns || [] }
  }
} };
